"""T-005 r4 9.5g: ladder v4 = the 9.5d rows (Fr 0.02 / 0.04 / 0.06, no arm swing) plus the 3D-aware rows from stride_opt_tc.py --yaw (arm swing + yaw moment balance + shared cone), and the Fr 0.10 target row as its own file.
Usage (project root): export_ladder95g.py 007=stride_fr007_v4_b.json 008=stride_fr008_v4_d.json 009=stride_fr009_v4_b.json 010=stride_fr010_v4_b.json   (rows Fr 0.07-0.09 fall back to the 9.5d v3_a row when not given / not FEASIBLE), Fr 0.10 goes to gait_reference_qp_v4.json (the ladder file never holds it: the loader appends the main file's row last).
Writes Assets/Game/Config/Mech/gait_reference_qp_ladder_v4.json and gait_reference_qp_v4.json; gait_reference_qp.json and the older ladders are untouched (the exporter takes an output path)."""
import json, pathlib, subprocess, sys, tempfile
ROOT = pathlib.Path.cwd(); OUTD = ROOT / "Assets/Game/Config/Mech"; O = ROOT / "Tools/GaitOpt/out"; given = dict(a.split("=") for a in sys.argv[1:])
low = ["stride_fr002_lat.json", "stride_fr004_lat.json", "stride_fr006_lat.json"]; high = {"007": "stride_fr007_v3_a.json", "008": "stride_fr008_v3_a.json", "009": "stride_fr009_v3_a.json"}
for f in high:
    c = O / given.get(f, "none")
    if c.exists() and json.load(open(c))["summary"]["verdict"] == "FEASIBLE": high[f] = c.name
def run(src):
    t = pathlib.Path(tempfile.mkstemp(suffix=".json")[1]); subprocess.run([sys.executable, "Tools/GaitOpt/export_reference_v2.py", str(O / src), str(t)], check=True); d = json.loads(t.read_text()); t.unlink(); return d
SRC = low + list(high.values()); rows = []; base = None
for s in SRC: d = run(s); rows += d["rows"]; base = base or d
base["rows"] = rows; base["notes"] = ("Speed ladder of the imp 3 start, v4 (T-005 r4 9.5g, qp_ladder): Fr 0.02-0.06 as 9.5d, Fr 0.07 / 0.08 / 0.09 from the 3D-aware optimisation (yaw moment balance, arm swing, shared cone) where FEASIBLE; "
                                      "rows with source *_v4_* carry stance/swing.shoulder_* arm trajectories. Generated by evidence/T-005/round4/scripts/export_ladder95g.py; do not edit by hand.")
base["source"]["files"] = SRC; base["source"]["verdicts"] = [f"{r['source_file']}: {r['verdict']}, fr {r['fr']}" for r in rows]
(OUTD / "gait_reference_qp_ladder_v4.json").write_text(json.dumps(base, indent=1))
tgt = run(given["010"]); tgt["notes"] = "Fr 0.10 target row of the 3D-aware stride (T-005 r4 9.5g), same schema as gait_reference_qp.json plus arm / yaw fields; generated by export_ladder95g.py; do not edit by hand."
(OUTD / "gait_reference_qp_v4.json").write_text(json.dumps(tgt, indent=1))
print("ladder v4", [(r["fr"], r["verdict"], r["source_file"], round(r["v"], 2), round(r["step_length_m"], 1)) for r in rows]); print("target", tgt["rows"][0]["fr"], tgt["rows"][0]["verdict"], tgt["rows"][0]["source_file"])
